/// <summary>
/// Process definition for Adding Count Line
/// </summary>
class MwmsProcessAddCountLine extends TFMProcess
{
}

Method.Source:
protected void new()
{
    TFMLogicBlock block = MwmsLogicBlockAddCountLine::Construct();
    processName = TFMConstants::AddCountLine();
    super();
    this.addBlock(block);
    this.blockCollection().addBlockAddon(block, new TFMLogicBlockAddonDisableValueTransfers());
}
